css:
@page {
    size: A4;
    margin: 0 !important;
    padding: 0 !important;
}

body, .print-format {
    margin: 0 !important;
    padding: 0 !important;
    font-family: "Times New Roman", serif;
    font-size: 15px;
    line-height: 1.6;
    color: #000;
    width: 100% !important;
    height: 100% !important;
}

.page {
    position: relative;
    width: 210mm;
    height: 297mm;
    margin: 0;
    overflow: hidden;
    background-image: url("/assets/sahayog/images/letter_head_and_footer_.png");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    box-sizing: border-box;
}

.page img.bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    z-index: 1;
}

.page .content {
    position: absolute;
    top: 40%;               
    left: 50%;              
    transform: translate(-50%, -50%);
    width: 80%;             
    z-index: 2;
    box-sizing: border-box;
    text-align: center;
}

.content h2 {
    margin-bottom: 10px;
    font-size: 22px;
    font-weight: bold;
    text-align: center;
}

.details p {
    margin: 0 0 10px 0;
    text-indent: 0;
    text-align: left;
}

.content p {
    margin: 0 0 1px 0;
    font-size: 15px;
    text-align: justify;
    text-indent: 30px;
}

.signature {
    margin-top: 60px;
    font-size: 15px;
    font-weight: bold;
    text-align: left;
}
